const parse=(v)=>typeof v==='string'?JSON.parse(v):v;
const c=parse(input.closed)||[];const up=(parse(input.up)||[]).concat(parse(input.up2)||[]);
const norm=(p)=>{p=String(p||'').replace(/\D/g,'');if(p.startsWith('972'))p='0'+p.slice(3);if(p.length===9)p='0'+p;return p;};
const aud={};up.forEach(r=>{r=[].concat(r);const p=norm(r[0]);if(p)aud[p]=String(r[3]||'?');});
const f={};c.forEach(x=>{const p=norm(x.a);if(!p)return;const s=String(x.s||'');let k='O';if(/לקוח פעיל/.test(s))k='A';else if(/לא ענה|לא עונה|אין מענה/.test(s))k='N';else if(/להסיר|מוטרד/.test(s))k='R';if(!f[p]||k==='A')f[p]=k;});
const t={};Object.keys(f).forEach(p=>{if(f[p]==='N')return;const a=aud[p]||'(אחר)';t[a]=t[a]||{n:0,A:0,R:0};t[a].n++;if(f[p]==='A')t[a].A++;if(f[p]==='R')t[a].R++;});
const rows=Object.keys(t).sort((x,y)=>t[y].n-t[x].n).map(a=>[a,t[a].n,t[a].A,Math.round(100*t[a].A/t[a].n)+'%',t[a].R]);
rows.unshift(['קהל','נענו ונסגרו','לקוח פעיל','אחוז פעילים','הסרה']);
for(let i=0;i<20;i++)rows.push(['','','','','']);rows.push(['עודכן: '+new Date().toISOString(),'','','','']);
return {body: JSON.stringify({values: rows})};
